import { Meta, StoryObj } from "@storybook/react";
import CartItem, { ItemInCart, CartItemProps } from "./cart-item";
import { action } from "storybook/actions";
import { useState } from "react";
import { RideStore } from "@/core/stores";
import { ProductBlockFragment } from "@/core/types";
import { PlaceholderImageHelper } from "../../../helpers";
import { ProductInformationResponseItem, WebshopProductType } from "@parksandresorts/webapiproxy-types";
import { StaticConfigContextType } from "@/core/contexts";
import { PageProviders } from "@/core/providers";
/**
 * Flatten the item props to the root level for Storybook controls
 * Otherwise we will get an ugly object control that is hard to use
 */
type CartItemStoryArgs = Omit<CartItemProps, "item"> &
  ItemInCart & {
    productData: { contentfulProduct?: ProductBlockFragment; glkProduct?: ProductInformationResponseItem };
  };

const meta: Meta<CartItemStoryArgs> = {
  title: "Modules/Cart/Cart Item",
  argTypes: {
    isDisabled: {
      control: "boolean",
    },
  },
  args: {
    deleteCartItem: (item: ItemInCart) => action("Delete item")(item),
    updateCartItemQuantity: (item: ItemInCart, newQuantity: number) =>
      action("Update item quantity")({ item, newQuantity }),
  },
  render: function PrimaryStory(args) {
    RideStore.getRideById = () => ({ rideId: 123, title: "Insane", contentful_id: "1" });
    PlaceholderImageHelper.getPlaceholderImage = () => "/mock-data/grona-lund-logo.svg";

    const [quantity, setQuantity] = useState(args.quantity);
    const [isDeleted, setIsDeleted] = useState(false);

    const handleUpdateQuantity = args.updateCartItemQuantity
      ? (item: ItemInCart, newQuantity: number) => {
          setQuantity(newQuantity);
          args.updateCartItemQuantity?.(item, newQuantity);
        }
      : undefined;

    const handleDeleteItem = args.deleteCartItem
      ? (item: ItemInCart) => {
          setIsDeleted(true);
          args.deleteCartItem?.(item);
        }
      : undefined;

    const {
      isDisabled,
      id,
      productId,
      name,
      price,
      unitPriceIncludingVat,
      minimumQuantity,
      stockQuantity,
      productData,
      previousTotalPrice,
      metadata,
      visitorName,
      subItems,
      redeemableItems,
      deliveryType,
    } = args;

    const item: ItemInCart = {
      id,
      productId,
      name,
      price,
      unitPriceIncludingVat,
      quantity,
      minimumQuantity,
      stockQuantity,
      previousTotalPrice,
      metadata,
      visitorName,
      subItems,
      redeemableItems,
      deliveryType,
      data: undefined,
      productType: productData.glkProduct?.productType ?? WebshopProductType.STANDARD,
    };

    if (isDeleted) {
      return (
        <div>
          Item {name} deleted.
          <button
            onClick={() => {
              setIsDeleted(false);
              setQuantity(args.quantity);
            }}
          >
            Reset story
          </button>
        </div>
      );
    }

    return (
      <PageProviders
        currentContentPageData={{ currentLocale: "sv" } as any}
        staticConfigData={{
          eCommerce: {} as StaticConfigContextType["eCommerce"],
          products: {
            contentfulProducts: productData.contentfulProduct ? [productData.contentfulProduct] : [],
            glkProducts: productData.glkProduct ? [productData.glkProduct] : [],
          },
        }}
      >
        <CartItem
          item={item}
          isDisabled={isDisabled}
          deleteCartItem={handleDeleteItem}
          updateCartItemQuantity={handleUpdateQuantity}
        />
      </PageProviders>
    );
  },
};

export default meta;

