import { PropsWithChildren } from "react";
import { MotionConfig } from "framer-motion";
import { QueryProvider } from "./query-provider";
import {
  JetpassModalContextProvider,
  CurrentContentPageContextProvider,
  CurrentContentPageContextType,
  ShopServiceCartContextProvider,
  StaticConfigContextProvider,
  StaticConfigContextType,
} from "../contexts";
import { ContentContainer } from "@/core/components/primitives/content-container/content-container";
import { QueryClientProviderProps } from "@tanstack/react-query";

export type Data = {
  currentContentPageData: CurrentContentPageContextType;
  staticConfigData: StaticConfigContextType;
  /** Overrides the query client. Mainly used in mocks for testing/storybook */
  overrideQueryClient?: QueryClientProviderProps["client"];
};

/**
 * This provider is used on the pages to gather multiple providers together. It currently includes:
 * - MotionConfig - Sets `reducedMotion="user"` so all framer-motion animations in the package respect the user's "prefers-reduced-motion" setting.
 *   NOTE: This only covers framer-motion. Animations from other libraries (e.g. canvas-confetti) are NOT affected and must handle
 *   "prefers-reduced-motion" themselves (e.g. canvas-confetti's `disableForReducedMotion: true`).
 * - QueryProvider - The provider for Tanstack query clients.
 * - JetpassModalContextProvider - The provider for the jepass modal's context.
 * - ShopServiceCartContextProvider - The new context for keeping tracks of carts going to the new ShopService.
 * - ContentContainer - A component which wraps the entire content of the web page. A reference to this is often used via `useContentContainerRef` and sent to Modals in order to remove mouse events on that element. (see `refWrapperElement` in modal.tsx)
 * - CurrentContentPageContextProvider - The provider for the current content page context.
 * - StaticConfigContextProvider - The provider for any static config set from the pages.
 */
export const PageProviders = ({
  children,
  currentContentPageData,
  staticConfigData,
  overrideQueryClient,
}: PropsWithChildren<Data>) => {
  return (
    <MotionConfig reducedMotion="user">
      <QueryProvider client={overrideQueryClient}>
        <JetpassModalContextProvider>
          <ShopServiceCartContextProvider currentLocale={currentContentPageData.currentLocale}>
            <ContentContainer>
              <CurrentContentPageContextProvider data={currentContentPageData}>
                <StaticConfigContextProvider data={staticConfigData}>{children}</StaticConfigContextProvider>
              </CurrentContentPageContextProvider>
            </ContentContainer>
          </ShopServiceCartContextProvider>
        </JetpassModalContextProvider>
      </QueryProvider>
    </MotionConfig>
  );
};
